-- =============================================================================
-- ClinicOS · 001 · Extensões e tipos enumerados
-- PostgreSQL 16+
-- =============================================================================

-- Extensões opcionais. Em produção (PostgreSQL/Supabase) todas devem existir.
-- O bloco tolera ambientes de teste embarcados que não as disponibilizam.
do $$
begin
  create extension if not exists pg_trgm;
exception when others then
  raise notice 'pg_trgm indisponível neste ambiente: %', sqlerrm;
end $$;

do $$
begin
  create extension if not exists btree_gist;
exception when others then
  raise notice 'btree_gist indisponível neste ambiente: %', sqlerrm;
end $$;

-- Perfis da plataforma -------------------------------------------------------
create type app_role as enum (
  'platform_admin',
  'clinic_admin',
  'doctor',
  'receptionist',
  'finance',
  'patient'
);

-- Plataforma / clínica -------------------------------------------------------
create type clinic_status as enum ('em_implantacao', 'ativa', 'suspensa', 'cancelada');
create type unit_type as enum ('matriz', 'filial', 'consultorio');
create type membership_status as enum ('convidado', 'ativo', 'suspenso', 'removido');
create type invite_status as enum ('pendente', 'aceito', 'expirado', 'cancelado');

-- Pessoas --------------------------------------------------------------------
create type patient_status as enum ('ativo', 'inativo', 'arquivado');
create type sex_type as enum ('feminino', 'masculino', 'intersexo', 'nao_informado');
create type consent_type as enum ('tratamento_dados', 'compartilhamento', 'telemedicina', 'marketing');

-- Agenda / atendimento -------------------------------------------------------
create type appointment_type as enum ('consulta', 'retorno', 'procedimento', 'teleconsulta', 'avaliacao');
create type appointment_status as enum (
  'agendada', 'confirmada', 'aguardando', 'em_atendimento',
  'realizada', 'cancelada', 'faltou'
);
create type payment_method as enum (
  'particular', 'pix', 'dinheiro', 'cartao_credito', 'cartao_debito',
  'boleto', 'convenio', 'transferencia', 'outro'
);

-- Documentação clínica -------------------------------------------------------
create type medical_record_status as enum ('rascunho', 'assinado', 'retificado', 'cancelado');
create type clinical_note_type as enum ('anamnese', 'evolucao', 'procedimento', 'adendo');
create type clinical_note_status as enum ('rascunho', 'assinado', 'retificado', 'cancelado');
create type allergy_severity as enum ('leve', 'moderada', 'grave');
create type prescription_type as enum ('simples', 'controle_especial', 'antimicrobiano', 'notificacao_a');
create type prescription_status as enum ('rascunho', 'emitida', 'cancelada');
create type signature_method as enum ('interno_hash', 'icp_brasil', 'certificado_digital');

-- Exames ---------------------------------------------------------------------
create type exam_priority as enum ('rotina', 'urgente', 'emergencia');
create type exam_order_status as enum ('solicitado', 'coletado', 'em_analise', 'resultado_disponivel', 'entregue', 'cancelado');
create type exam_item_status as enum ('solicitado', 'coletado', 'em_analise', 'resultado_disponivel', 'cancelado');
create type exam_result_status as enum ('preliminar', 'liberado', 'retificado', 'cancelado');

-- Convênios ------------------------------------------------------------------
create type claim_status as enum ('rascunho', 'enviada', 'em_analise', 'aprovada', 'glosada', 'paga', 'cancelada');

-- Financeiro / estoque -------------------------------------------------------
create type transaction_type as enum ('receita', 'despesa');
create type transaction_status as enum ('pendente', 'pago', 'atrasado', 'cancelado');
create type inventory_status as enum ('ativo', 'inativo');
create type inventory_movement_type as enum ('entrada', 'saida', 'ajuste', 'perda');

-- Assinaturas / plataforma ---------------------------------------------------
create type subscription_status as enum ('em_teste', 'ativa', 'inadimplente', 'suspensa', 'vencida', 'cancelada');
create type billing_period as enum ('mensal', 'anual');
create type gateway_type as enum ('manual', 'stripe', 'asaas', 'pagseguro', 'mercadopago');
create type invoice_status as enum ('aberta', 'paga', 'vencida', 'cancelada', 'reembolsada');
create type module_category as enum ('operacao', 'clinico', 'gestao', 'cadastros', 'relacionamento', 'sistema', 'plataforma');
create type module_audience as enum ('clinica', 'plataforma');
create type module_source as enum ('plano', 'adicional', 'cortesia');

-- Comunicação / IA / auditoria ----------------------------------------------
create type notification_type as enum ('consulta', 'financeiro', 'exame', 'sistema', 'whatsapp');
create type whatsapp_direction as enum ('enviada', 'recebida');
create type whatsapp_status as enum ('pendente', 'enviada', 'entregue', 'lida', 'erro');
create type ai_feature as enum ('resumo', 'apoio_documentacao', 'busca', 'organizacao', 'outro');
create type ai_status as enum ('pendente', 'concluida', 'erro', 'bloqueada');
create type audit_action as enum ('insert', 'update', 'delete', 'login', 'logout', 'view', 'export', 'sign', 'payment');

-- ============================================================================= -- ClinicOS · 002 · Plataforma, organizações e pessoas -- =============================================================================
-- Identidade global ----------------------------------------------------------- create table users ( id uuid primary key default gen_random_uuid(), email text not null, password_hash text, full_name text not null, phone text, avatar_url text, status text not null default 'ativo' check (status in ('ativo', 'inativo', 'bloqueado')), email_verified_at timestamptz, last_login_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); create unique index users_email_uidx on users (lower(email));
create table platform_admins ( id uuid primary key default gen_random_uuid(), user_id uuid not null unique references users(id) on delete cascade, status text not null default 'ativo' check (status in ('ativo', 'inativo')), granted_by uuid references users(id) on delete set null, created_at timestamptz not null default now() );
-- Catálogo comercial ---------------------------------------------------------- create table plans ( id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text, monthly_price numeric(12,2) not null default 0 check (monthly_price >= 0), annual_price numeric(12,2) not null default 0 check (annual_price >= 0), user_limit integer not null default 0 check (user_limit >= 0), professional_limit integer not null default 0 check (professional_limit >= 0), unit_limit integer not null default 0 check (unit_limit >= 0), patient_limit integer not null default 0 check (patient_limit >= 0), storage_gb integer not null default 0 check (storage_gb >= 0), ai_interaction_limit integer not null default 0 check (ai_interaction_limit >= 0), message_limit integer not null default 0 check (message_limit >= 0), trial_days integer not null default 14 check (trial_days >= 0), is_active boolean not null default true, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create table modules ( id uuid primary key default gen_random_uuid(), key text not null unique, name text not null, description text, category module_category not null, audience module_audience not null default 'clinica', icon text, route text, is_core boolean not null default false, is_plan boolean not null default true, is_active boolean not null default true, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create table module_features ( id uuid primary key default gen_random_uuid(), module_id uuid not null references modules(id) on delete cascade, key text not null, name text not null, description text, sort_order integer not null default 0, created_at timestamptz not null default now(), unique (module_id, key) );
create table plan_modules ( plan_id uuid not null references plans(id) on delete cascade, module_id uuid not null references modules(id) on delete cascade, created_at timestamptz not null default now(), primary key (plan_id, module_id) );
create table platform_settings ( key text primary key, value jsonb not null default '{}'::jsonb, updated_by uuid references users(id) on delete set null, updated_at timestamptz not null default now() );
-- Organização (tenant) -------------------------------------------------------- create table clinics ( id uuid primary key default gen_random_uuid(), legal_name text not null, trade_name text, display_name text not null, cnpj text, state_registration text, email text, phone text, whatsapp text, cep text, address text, address_number text, complement text, neighborhood text, city text, state char(2), legal_representative_name text, legal_representative_cpf text, legal_representative_email text, legal_representative_phone text, status clinic_status not null default 'em_implantacao', portal_slug text unique, logo_url text, timezone text not null default 'America/Sao_Paulo', notes text, settings jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint clinics_cnpj_fmt check (cnpj is null or cnpj ~ '^[0-9]{14}$'), constraint clinics_cpf_fmt check (legal_representative_cpf is null or legal_representative_cpf ~ '^[0-9]{11}$'), constraint clinics_state_fmt check (state is null or state ~ '^[A-Z]{2}$') );
create table clinic_units ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, name text not null, type unit_type not null default 'filial', internal_code text, phone text, email text, cep text, address text, address_number text, complement text, neighborhood text, city text, state char(2), manager_name text, opening_hours text, is_headquarters boolean not null default false, status text not null default 'ativa' check (status in ('ativa', 'inativa')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint clinic_units_state_fmt check (state is null or state ~ '^[A-Z]{2}$') ); create unique index clinic_units_internal_code_uidx on clinic_units (clinic_id, internal_code) where internal_code is not null;
create table clinic_memberships ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, user_id uuid not null references users(id) on delete cascade, role app_role not null check (role in ('clinic_admin', 'doctor', 'receptionist', 'finance')), status membership_status not null default 'convidado', job_title text, hired_at date, invited_by uuid references users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (clinic_id, user_id) );
create table membership_units ( membership_id uuid not null references clinic_memberships(id) on delete cascade, unit_id uuid not null references clinic_units(id) on delete cascade, clinic_id uuid not null references clinics(id) on delete cascade, primary key (membership_id, unit_id) );
create table user_invites ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, email text not null, full_name text, role app_role not null check (role in ('clinic_admin', 'doctor', 'receptionist', 'finance')), token_hash text not null unique, status invite_status not null default 'pendente', expires_at timestamptz not null, accepted_at timestamptz, invited_by uuid references users(id) on delete set null, created_at timestamptz not null default now() );
-- Profissionais --------------------------------------------------------------- create table professionals ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, user_id uuid references users(id) on delete set null, full_name text not null, council text, council_number text, council_state char(2), specialties text[] not null default '{}', phone text, email text, consultation_price numeric(12,2) not null default 0 check (consultation_price >= 0), default_duration_min integer not null default 30 check (default_duration_min > 0), commission_percent numeric(5,2) not null default 0 check (commission_percent between 0 and 100), calendar_color text not null default '#0EA5E9', status text not null default 'ativo' check (status in ('ativo', 'inativo')), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint professionals_state_fmt check (council_state is null or council_state ~ '^[A-Z]{2}$') ); create unique index professionals_council_uidx on professionals (clinic_id, council, council_number, council_state) where council is not null and council_number is not null and council_state is not null;
create table professional_units ( professional_id uuid not null references professionals(id) on delete cascade, unit_id uuid not null references clinic_units(id) on delete cascade, clinic_id uuid not null references clinics(id) on delete cascade, primary key (professional_id, unit_id) );
create table professional_schedules ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, professional_id uuid not null references professionals(id) on delete cascade, unit_id uuid not null references clinic_units(id) on delete cascade, weekday smallint not null check (weekday between 0 and 6), start_time time not null, end_time time not null, slot_minutes integer not null default 30 check (slot_minutes > 0), valid_from date, valid_to date, is_active boolean not null default true, created_at timestamptz not null default now(), constraint professional_schedules_time_check check (end_time > start_time) );
create table schedule_blocks ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, professional_id uuid not null references professionals(id) on delete cascade, unit_id uuid references clinic_units(id) on delete set null, starts_at timestamptz not null, ends_at timestamptz not null, reason text, created_by uuid references users(id) on delete set null, created_at timestamptz not null default now(), constraint schedule_blocks_range_check check (ends_at > starts_at) );
-- Convênios (catálogo global + contrato por clínica) -------------------------- create table insurance_providers ( id uuid primary key default gen_random_uuid(), name text not null, ans_registration text unique, cnpj text, contact_email text, contact_phone text, status text not null default 'ativo' check (status in ('ativo', 'inativo')), created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create table clinic_insurance_contracts ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, provider_id uuid not null references insurance_providers(id) on delete restrict, status text not null default 'ativo' check (status in ('ativo', 'inativo')), payment_term_days integer not null default 30 check (payment_term_days >= 0), default_table text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (clinic_id, provider_id) );
-- Pacientes ------------------------------------------------------------------- create table patients ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, full_name text not null, social_name text, cpf text, birth_date date, sex sex_type not null default 'nao_informado', gender text, email text, phone text, whatsapp text, cep text, address text, address_number text, complement text, neighborhood text, city text, state char(2), insurance_provider_id uuid references insurance_providers(id) on delete set null, insurance_member_number text, emergency_contact_name text, emergency_contact_phone text, notes text, status patient_status not null default 'ativo', preferred_unit_id uuid references clinic_units(id) on delete set null, lgpd_consent_at timestamptz, lgpd_consent_by uuid references users(id) on delete set null, photo_url text, created_by uuid references users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint patients_cpf_fmt check (cpf is null or cpf ~ '^[0-9]{11}$'), constraint patients_state_fmt check (state is null or state ~ '^[A-Z]{2}$') ); create unique index patients_clinic_cpf_uidx on patients (clinic_id, cpf) where cpf is not null; do $$ begin if exists (select 1 from pg_extension where extname = 'pg_trgm') then create index if not exists patients_name_trgm_idx on patients using gin (full_name gin_trgm_ops); else create index if not exists patients_name_idx on patients (full_name); end if; end $$;
create table patient_portal_access ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, patient_id uuid not null references patients(id) on delete cascade, user_id uuid not null references users(id) on delete cascade, status text not null default 'ativo' check (status in ('ativo', 'revogado')), granted_at timestamptz not null default now(), revoked_at timestamptz, unique (patient_id, user_id) );
create table patient_consents ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, patient_id uuid not null references patients(id) on delete cascade, type consent_type not null, granted boolean not null default false, granted_at timestamptz, revoked_at timestamptz, evidence jsonb not null default '{}'::jsonb, document_version text, created_by uuid references users(id) on delete set null, created_at timestamptz not null default now() );

-- ============================================================================= -- ClinicOS · 003 · Agenda, atendimento e documentação clínica -- =============================================================================
create table appointments ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, unit_id uuid not null references clinic_units(id) on delete restrict, patient_id uuid not null references patients(id) on delete restrict, professional_id uuid not null references professionals(id) on delete restrict, type appointment_type not null default 'consulta', status appointment_status not null default 'agendada', scheduled_start timestamptz not null, scheduled_end timestamptz not null, checked_in_at timestamptz, started_at timestamptz, finished_at timestamptz, payment_method payment_method not null default 'particular', amount numeric(12,2) not null default 0 check (amount >= 0), insurance_provider_id uuid references insurance_providers(id) on delete set null, notes text, cancellation_reason text, cancelled_by uuid references users(id) on delete set null, rescheduled_from_id uuid references appointments(id) on delete set null, created_by uuid references users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint appointments_range_check check (scheduled_end > scheduled_start) );
create table appointment_status_history ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, appointment_id uuid not null references appointments(id) on delete cascade, from_status appointment_status, to_status appointment_status not null, changed_by uuid references users(id) on delete set null, notes text, created_at timestamptz not null default now() );
create table waiting_list ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, unit_id uuid not null references clinic_units(id) on delete cascade, patient_id uuid not null references patients(id) on delete cascade, professional_id uuid references professionals(id) on delete set null, priority smallint not null default 3 check (priority between 1 and 5), desired_from timestamptz, desired_to timestamptz, notes text, status text not null default 'aguardando' check (status in ('aguardando', 'contatado', 'agendado', 'cancelado')), created_by uuid references users(id) on delete set null, created_at timestamptz not null default now() );
-- Prontuário ------------------------------------------------------------------ create table medical_records ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, patient_id uuid not null references patients(id) on delete restrict, professional_id uuid not null references professionals(id) on delete restrict, appointment_id uuid references appointments(id) on delete set null, record_date timestamptz not null default now(), chief_complaint text, history_present_illness text, physical_exam text, assessment text, plan text, icd10_codes text[] not null default '{}', status medical_record_status not null default 'rascunho', version integer not null default 1 check (version > 0), parent_id uuid references medical_records(id) on delete set null, signed_at timestamptz, signed_by uuid references users(id) on delete set null, signature_method signature_method, content_hash text, signature_hash text, verification_code text unique, created_by uuid references users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); create unique index medical_records_appointment_uidx on medical_records (appointment_id) where appointment_id is not null;
create table clinical_notes ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, medical_record_id uuid not null references medical_records(id) on delete cascade, patient_id uuid not null references patients(id) on delete restrict, professional_id uuid not null references professionals(id) on delete restrict, note_type clinical_note_type not null default 'evolucao', content text not null, status clinical_note_status not null default 'rascunho', parent_note_id uuid references clinical_notes(id) on delete set null, signed_at timestamptz, signed_by uuid references users(id) on delete set null, signature_method signature_method, content_hash text, created_by uuid references users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create table allergies ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, patient_id uuid not null references patients(id) on delete cascade, substance text not null, reaction text, severity allergy_severity not null default 'moderada', notes text, status text not null default 'ativo' check (status in ('ativo', 'inativo')), noted_by uuid references users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
-- Medicamentos: linha global (clinic_id nulo) ou customizada da clínica -------- create table medications ( id uuid primary key default gen_random_uuid(), clinic_id uuid references clinics(id) on delete cascade, name text not null, active_ingredient text, presentation text, controlled_class text, anvisa_code text, default_dosage text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); do $$ begin if exists (select 1 from pg_extension where extname = 'pg_trgm') then create index if not exists medications_name_trgm_idx on medications using gin (name gin_trgm_ops); else create index if not exists medications_name_idx on medications (name); end if; end $$;
create table prescriptions ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, patient_id uuid not null references patients(id) on delete restrict, professional_id uuid not null references professionals(id) on delete restrict, appointment_id uuid references appointments(id) on delete set null, medical_record_id uuid references medical_records(id) on delete set null, type prescription_type not null default 'simples', status prescription_status not null default 'rascunho', issued_at timestamptz, verification_code text unique, notes text, content_hash text, signature_hash text, signature_method signature_method, signed_at timestamptz, signed_by uuid references users(id) on delete set null, pdf_url text, created_by uuid references users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create table prescription_items ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, prescription_id uuid not null references prescriptions(id) on delete cascade, medication_id uuid references medications(id) on delete set null, medication_name text not null, dose text, frequency text, duration text, route text, quantity numeric(12,3), instructions text, sort_order integer not null default 0, created_at timestamptz not null default now() );
-- Exames ---------------------------------------------------------------------- create table exam_catalog ( id uuid primary key default gen_random_uuid(), clinic_id uuid references clinics(id) on delete cascade, tuss_code text, name text not null, exam_type text, sample_type text, preparation text, reference_price numeric(12,2) check (reference_price is null or reference_price >= 0), is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); do $$ begin if exists (select 1 from pg_extension where extname = 'pg_trgm') then create index if not exists exam_catalog_name_trgm_idx on exam_catalog using gin (name gin_trgm_ops); else create index if not exists exam_catalog_name_idx on exam_catalog (name); end if; end $$;
create table exam_orders ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, patient_id uuid not null references patients(id) on delete restrict, professional_id uuid not null references professionals(id) on delete restrict, appointment_id uuid references appointments(id) on delete set null, medical_record_id uuid references medical_records(id) on delete set null, order_date timestamptz not null default now(), priority exam_priority not null default 'rotina', status exam_order_status not null default 'solicitado', laboratory text, clinical_indication text, notes text, verification_code text unique, created_by uuid references users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create table exam_order_items ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, exam_order_id uuid not null references exam_orders(id) on delete cascade, exam_catalog_id uuid references exam_catalog(id) on delete set null, exam_name text not null, tuss_code text, status exam_item_status not null default 'solicitado', sort_order integer not null default 0, created_at timestamptz not null default now() );
create table exam_results ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, exam_order_id uuid not null references exam_orders(id) on delete cascade, exam_order_item_id uuid references exam_order_items(id) on delete cascade, result_summary text, result_text text, reference_range text, attachment_path text, released_by uuid references users(id) on delete set null, released_at timestamptz, status exam_result_status not null default 'preliminar', created_at timestamptz not null default now(), updated_at timestamptz not null default now() );

-- ============================================================================= -- ClinicOS · 004 · Financeiro, estoque, comunicação, assinaturas e auditoria -- =============================================================================
create table financial_categories ( id uuid primary key default gen_random_uuid(), clinic_id uuid references clinics(id) on delete cascade, name text not null, type transaction_type not null, is_system boolean not null default false, created_at timestamptz not null default now() ); create unique index financial_categories_clinic_uidx on financial_categories (clinic_id, lower(name), type) where clinic_id is not null; create unique index financial_categories_global_uidx on financial_categories (lower(name), type) where clinic_id is null;
create table insurance_claims ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, patient_id uuid not null references patients(id) on delete restrict, provider_id uuid not null references insurance_providers(id) on delete restrict, appointment_id uuid references appointments(id) on delete set null, guide_number text not null, tuss_code text, procedure_name text, presented_amount numeric(12,2) not null default 0 check (presented_amount >= 0), approved_amount numeric(12,2) check (approved_amount is null or approved_amount >= 0), status claim_status not null default 'rascunho', sent_at date, approved_at date, paid_at date, notes text, created_by uuid references users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (clinic_id, provider_id, guide_number) );
create table financial_transactions ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, unit_id uuid references clinic_units(id) on delete set null, category_id uuid references financial_categories(id) on delete set null, type transaction_type not null, description text not null, amount numeric(12,2) not null check (amount > 0), due_date date not null, paid_at date, status transaction_status not null default 'pendente', payment_method payment_method, patient_id uuid references patients(id) on delete set null, appointment_id uuid references appointments(id) on delete set null, professional_id uuid references professionals(id) on delete set null, insurance_claim_id uuid references insurance_claims(id) on delete set null, invoice_number text, notes text, created_by uuid references users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create table inventory_items ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, unit_id uuid references clinic_units(id) on delete set null, name text not null, category text, sku text, quantity numeric(14,3) not null default 0 check (quantity >= 0), minimum_quantity numeric(14,3) not null default 0 check (minimum_quantity >= 0), unit_of_measure text not null default 'un', unit_cost numeric(12,2) not null default 0 check (unit_cost >= 0), sale_price numeric(12,2) check (sale_price is null or sale_price >= 0), supplier text, batch text, expires_at date, location text, status inventory_status not null default 'ativo', created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); create unique index inventory_items_sku_uidx on inventory_items (clinic_id, sku) where sku is not null;
create table inventory_movements ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, item_id uuid not null references inventory_items(id) on delete cascade, type inventory_movement_type not null, quantity numeric(14,3) not null check (quantity > 0), unit_cost numeric(12,2), reason text, reference text, performed_by uuid references users(id) on delete set null, created_at timestamptz not null default now() );
-- Documentos e integridade ---------------------------------------------------- create table documents ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, patient_id uuid not null references patients(id) on delete restrict, medical_record_id uuid references medical_records(id) on delete set null, document_type text not null, title text not null, file_path text not null, mime_type text, file_size bigint check (file_size is null or file_size >= 0), sha256 text, signed_at timestamptz, signed_by uuid references users(id) on delete set null, signature_method signature_method, verification_code text unique, created_by uuid references users(id) on delete set null, created_at timestamptz not null default now() );
create table notifications ( id uuid primary key default gen_random_uuid(), clinic_id uuid references clinics(id) on delete cascade, user_id uuid not null references users(id) on delete cascade, type notification_type not null default 'sistema', title text not null, body text, data jsonb not null default '{}'::jsonb, read_at timestamptz, created_at timestamptz not null default now() );
create table whatsapp_messages ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, patient_id uuid references patients(id) on delete set null, appointment_id uuid references appointments(id) on delete set null, user_id uuid references users(id) on delete set null, direction whatsapp_direction not null default 'enviada', template_key text, body text not null, status whatsapp_status not null default 'pendente', external_id text, error_message text, sent_at timestamptz, created_at timestamptz not null default now() );
create table ai_interactions ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, user_id uuid not null references users(id) on delete restrict, patient_id uuid references patients(id) on delete set null, feature ai_feature not null, prompt text not null, response text, model text, prompt_tokens integer, completion_tokens integer, safety_flags jsonb not null default '{}'::jsonb, status ai_status not null default 'pendente', reviewed_by uuid references users(id) on delete set null, reviewed_at timestamptz, created_at timestamptz not null default now() );
-- Assinaturas e entitlements -------------------------------------------------- create table subscriptions ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null unique references clinics(id) on delete cascade, plan_id uuid not null references plans(id) on delete restrict, status subscription_status not null default 'em_teste', periodicity billing_period not null default 'mensal', price numeric(12,2) not null default 0 check (price >= 0), discount numeric(12,2) not null default 0 check (discount >= 0), started_at date not null default current_date, current_period_start date, current_period_end date, trial_ends_at date, gateway gateway_type not null default 'manual', gateway_subscription_id text, cancelled_at timestamptz, cancellation_reason text, created_by uuid references users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create table subscription_invoices ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, subscription_id uuid not null references subscriptions(id) on delete cascade, amount numeric(12,2) not null check (amount >= 0), due_date date not null, paid_at date, status invoice_status not null default 'aberta', gateway gateway_type not null default 'manual', external_id text unique, receipt_url text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create table clinic_modules ( id uuid primary key default gen_random_uuid(), clinic_id uuid not null references clinics(id) on delete cascade, module_id uuid not null references modules(id) on delete cascade, enabled boolean not null default true, source module_source not null default 'plano', price numeric(12,2) not null default 0 check (price >= 0), activated_at timestamptz, expires_at timestamptz, created_by uuid references users(id) on delete set null, created_at timestamptz not null default now(), unique (clinic_id, module_id) );
create table clinic_features ( clinic_id uuid not null references clinics(id) on delete cascade, feature_id uuid not null references module_features(id) on delete cascade, enabled boolean not null default true, updated_at timestamptz not null default now(), primary key (clinic_id, feature_id) );
create table gateway_events ( id uuid primary key default gen_random_uuid(), gateway gateway_type not null, external_event_id text not null unique, event_type text, payload jsonb not null default '{}'::jsonb, processed_at timestamptz, error text, created_at timestamptz not null default now() );
-- Auditoria -------------------------------------------------------------------- create table audit_logs ( id bigint generated always as identity primary key, clinic_id uuid references clinics(id) on delete set null, actor_user_id uuid references users(id) on delete set null, actor_role app_role, action audit_action not null, entity text not null, entity_id text, before_data jsonb, after_data jsonb, ip inet, user_agent text, request_id text, prev_hash text, hash text not null, created_at timestamptz not null default now() ); create index audit_logs_clinic_created_idx on audit_logs (clinic_id, created_at desc);
create table record_access_logs ( id bigint generated always as identity primary key, clinic_id uuid not null references clinics(id) on delete cascade, medical_record_id uuid not null references medical_records(id) on delete cascade, user_id uuid references users(id) on delete set null, action text not null default 'view', ip inet, created_at timestamptz not null default now() );

