alter table professional_units
  add constraint professional_units_professional_fk
  foreign key (professional_id, clinic_id) references professionals (id, clinic_id) on delete cascade;
alter table professional_units
  add constraint professional_units_unit_fk
  foreign key (unit_id, clinic_id) references clinic_units (id, clinic_id) on delete cascade;

alter table professional_schedules
  add constraint professional_schedules_professional_fk
  foreign key (professional_id, clinic_id) references professionals (id, clinic_id) on delete cascade;

alter table appointments
  add constraint appointments_unit_fk
  foreign key (unit_id, clinic_id) references clinic_units (id, clinic_id) on delete restrict;
alter table appointments
  add constraint appointments_patient_fk
  foreign key (patient_id, clinic_id) references patients (id, clinic_id) on delete restrict;
alter table appointments
  add constraint appointments_professional_fk
  foreign key (professional_id, clinic_id) references professionals (id, clinic_id) on delete restrict;

alter table appointment_status_history
  add constraint appointment_history_appointment_fk
  foreign key (appointment_id, clinic_id) references appointments (id, clinic_id) on delete cascade;

alter table medical_records
  add constraint medical_records_patient_fk
  foreign key (patient_id, clinic_id) references patients (id, clinic_id) on delete restrict;
alter table medical_records
  add constraint medical_records_professional_fk
  foreign key (professional_id, clinic_id) references professionals (id, clinic_id) on delete restrict;

alter table clinical_notes
  add constraint clinical_notes_record_fk
  foreign key (medical_record_id, clinic_id) references medical_records (id, clinic_id) on delete cascade;

alter table prescriptions
  add constraint prescriptions_patient_fk
  foreign key (patient_id, clinic_id) references patients (id, clinic_id) on delete restrict;
alter table prescriptions
  add constraint prescriptions_professional_fk
  foreign key (professional_id, clinic_id) references professionals (id, clinic_id) on delete restrict;

alter table prescription_items
  add constraint prescription_items_prescription_fk
  foreign key (prescription_id, clinic_id) references prescriptions (id, clinic_id) on delete cascade;

alter table exam_orders
  add constraint exam_orders_patient_fk
  foreign key (patient_id, clinic_id) references patients (id, clinic_id) on delete restrict;
alter table exam_orders
  add constraint exam_orders_professional_fk
  foreign key (professional_id, clinic_id) references professionals (id, clinic_id) on delete restrict;

alter table exam_order_items
  add constraint exam_order_items_order_fk
  foreign key (exam_order_id, clinic_id) references exam_orders (id, clinic_id) on delete cascade;

alter table exam_results
  add constraint exam_results_order_fk
  foreign key (exam_order_id, clinic_id) references exam_orders (id, clinic_id) on delete cascade;

alter table insurance_claims
  add constraint insurance_claims_patient_fk
  foreign key (patient_id, clinic_id) references patients (id, clinic_id) on delete restrict;

alter table financial_transactions
  add constraint financial_transactions_patient_fk
  foreign key (patient_id, clinic_id) references patients (id, clinic_id) on delete restrict;

alter table inventory_movements
  add constraint inventory_movements_item_fk
  foreign key (item_id, clinic_id) references inventory_items (id, clinic_id) on delete cascade;

alter table documents
  add constraint documents_patient_fk
  foreign key (patient_id, clinic_id) references patients (id, clinic_id) on delete restrict;

alter table subscription_invoices
  add constraint subscription_invoices_subscription_fk
  foreign key (subscription_id, clinic_id) references subscriptions (id, clinic_id) on delete cascade;

-- Índices de tenant ------------------------------------------------------------
do $$
declare
  t text;
begin
  foreach t in array array[
    'clinic_units', 'clinic_memberships', 'membership_units', 'user_invites',
    'professionals', 'professional_units', 'professional_schedules', 'schedule_blocks',
    'clinic_insurance_contracts', 'patients', 'patient_portal_access', 'patient_consents',
    'appointments', 'appointment_status_history', 'waiting_list',
    'medical_records', 'clinical_notes', 'allergies', 'medications',
    'prescriptions', 'prescription_items', 'exam_catalog', 'exam_orders',
    'exam_order_items', 'exam_results', 'financial_categories', 'insurance_claims',
    'financial_transactions', 'inventory_items', 'inventory_movements', 'documents',
    'notifications', 'whatsapp_messages', 'ai_interactions', 'subscriptions',
    'subscription_invoices', 'clinic_modules', 'clinic_features', 'record_access_logs'
  ]
  loop
    execute format('create index if not exists %I on %I (clinic_id)', t || '_clinic_idx', t);
  end loop;
end $$;

create index if not exists appointments_start_idx on appointments (clinic_id, scheduled_start);
create index if not exists appointments_professional_idx on appointments (professional_id, scheduled_start);
create index if not exists appointments_patient_idx on appointments (patient_id, scheduled_start);
create index if not exists appointments_status_idx on appointments (clinic_id, status);
create index if not exists prescriptions_issued_idx on prescriptions (clinic_id, issued_at desc);
create index if not exists exam_orders_status_idx on exam_orders (clinic_id, status);
create index if not exists financial_due_idx on financial_transactions (clinic_id, due_date);
create index if not exists financial_status_idx on financial_transactions (clinic_id, status);
create index if not exists patients_phone_idx on patients (clinic_id, phone);
create index if not exists notifications_user_idx on notifications (user_id, read_at);
create index if not exists whatsapp_status_idx on whatsapp_messages (clinic_id, status);

-- Impede dupla marcação do mesmo profissional no mesmo horário -----------------
do $$
begin
  if exists (select 1 from pg_extension where extname = 'btree_gist') then
    alter table appointments
      add constraint appointments_professional_no_overlap
      exclude using gist (
        professional_id with =,
        tstzrange(scheduled_start, scheduled_end, '[)') with &&
      ) where (status not in ('cancelada', 'faltou'));
  else
    raise notice 'btree_gist indisponível: constraint de não sobreposição não criada.';
  end if;
end $$;

-- updated_at automático -------------------------------------------------------
create or replace function fn_set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array[
    'users', 'plans', 'modules', 'clinics', 'clinic_units', 'clinic_memberships',
    'professionals', 'patients', 'appointments', 'medical_records', 'clinical_notes',
    'allergies', 'medications', 'prescriptions', 'exam_catalog', 'exam_orders',
    'exam_results', 'insurance_providers', 'clinic_insurance_contracts',
    'insurance_claims', 'financial_transactions', 'inventory_items',
    'subscriptions', 'subscription_invoices'
  ]
  loop
    execute format(
      'create trigger trg_%I_updated_at before update on %I for each row execute function fn_set_updated_at()',
      t, t
    );
  end loop;
end $$;

-- ============================================================================= -- ClinicOS · 006 · Catálogo de permissões, funções de sessão e views seguras -- =============================================================================
create table permissions ( id uuid primary key default gen_random_uuid(), module_id uuid references modules(id) on delete cascade, key text not null unique, action text not null, description text, created_at timestamptz not null default now() );
create table role_permissions ( role app_role not null, permission_id uuid not null references permissions(id) on delete cascade, created_at timestamptz not null default now(), primary key (role, permission_id) );
-- Contexto de sessão ----------------------------------------------------------- -- O backend define, por transação: -- select set_config('app.user_id', '<uuid>', true); -- select set_config('app.clinic_id', '<uuid>', true); create or replace function app_current_user_id() returns uuid language sql stable as $$ select nullif(current_setting('app.user_id', true), '')::uuid $$;
create or replace function app_current_clinic_id() returns uuid language sql stable as $$ select nullif(current_setting('app.clinic_id', true), '')::uuid $$;
-- Helpers com SECURITY DEFINER para consultar vínculos sem recursão de RLS ----- create or replace function app_is_platform_admin() returns boolean language sql stable security definer set search_path = public, pg_temp as $$ select exists ( select 1 from platform_admins pa where pa.user_id = app_current_user_id() and pa.status = 'ativo' ) $$;
create or replace function app_is_member_of_clinic(p_clinic uuid) returns boolean language sql stable security definer set search_path = public, pg_temp as $$ select exists ( select 1 from clinic_memberships m where m.clinic_id = p_clinic and m.user_id = app_current_user_id() and m.status = 'ativo' ) $$;
create or replace function app_has_any_role(p_clinic uuid, p_roles text[]) returns boolean language sql stable security definer set search_path = public, pg_temp as $$ select exists ( select 1 from clinic_memberships m where m.clinic_id = p_clinic and m.user_id = app_current_user_id() and m.status = 'ativo' and m.role::text = any (p_roles) ) $$;
create or replace function app_has_permission(p_clinic uuid, p_permission text) returns boolean language sql stable security definer set search_path = public, pg_temp as $$ select exists ( select 1 from clinic_memberships m join role_permissions rp on rp.role = m.role join permissions p on p.id = rp.permission_id where m.clinic_id = p_clinic and m.user_id = app_current_user_id() and m.status = 'ativo' and p.key = p_permission ) $$;
create or replace function app_professional_id(p_clinic uuid) returns uuid language sql stable security definer set search_path = public, pg_temp as $$ select pr.id from professionals pr where pr.clinic_id = p_clinic and pr.user_id = app_current_user_id() and pr.status = 'ativo' limit 1 $$;
create or replace function app_owns_patient(p_patient uuid) returns boolean language sql stable security definer set search_path = public, pg_temp as $$ select exists ( select 1 from patient_portal_access a where a.patient_id = p_patient and a.user_id = app_current_user_id() and a.status = 'ativo' ) $$;
create or replace function app_shares_clinic_with_user(p_user uuid) returns boolean language sql stable security definer set search_path = public, pg_temp as $$ select exists ( select 1 from clinic_memberships me join clinic_memberships other on other.clinic_id = me.clinic_id where me.user_id = app_current_user_id() and me.status = 'ativo' and me.role = 'clinic_admin' and other.user_id = p_user and other.status = 'ativo' ) $$;
-- Mascaramento de CPF para perfis sem permissão de dado sensível --------------- create or replace function app_mask_cpf(p_cpf text) returns text language sql immutable as $$ select case when p_cpf is null or length(p_cpf) <> 11 then p_cpf else '***.***.***-' || right(p_cpf, 2) end $$;
-- View de diretório com campo mascarado por perfil ----------------------------- create or replace view v_patients_directory with (security_invoker = true) as select p.id, p.clinic_id, p.full_name, p.social_name, case when app_has_permission(p.clinic_id, 'pacientes:view_sensitive') then p.cpf else app_mask_cpf(p.cpf) end as cpf, p.birth_date, p.sex, p.email, p.phone, p.whatsapp, p.city, p.state, p.status, ip.name as insurance_provider_name from patients p left join insurance_providers ip on ip.id = p.insurance_provider_id;

-- =============================================================================
-- ClinicOS · 007 · Row Level Security: tabelas operacionais e dados clínicos
-- =============================================================================
-- Estratégia: banco único, schema compartilhado, discriminador clinic_id.
-- O backend sempre define app.user_id e app.clinic_id na transação.
-- O papel de runtime NÃO é owner das tabelas; portanto a RLS é aplicada.
-- Funções SECURITY DEFINER (owner) consultam vínculos sem recursão.
-- =============================================================================

-- Tabelas genéricas: leitura por papéis, escrita por papéis, exclusão por papéis
do $$
declare
  r record;
begin
  for r in
    select * from (values
      ('clinic_units',              array['clinic_admin','doctor','receptionist','finance'], array['clinic_admin'],                          array['clinic_admin']),
      ('membership_units',          array['clinic_admin'],                                     array['clinic_admin'],                          array['clinic_admin']),
      ('professionals',             array['clinic_admin','doctor','receptionist','finance'], array['clinic_admin'],                          array['clinic_admin']),
      ('professional_units',        array['clinic_admin','doctor','receptionist','finance'], array['clinic_admin'],                          array['clinic_admin']),
      ('professional_schedules',    array['clinic_admin','doctor','receptionist','finance'], array['clinic_admin','receptionist'],           array['clinic_admin','receptionist']),
      ('schedule_blocks',           array['clinic_admin','doctor','receptionist','finance'], array['clinic_admin','receptionist'],           array['clinic_admin','receptionist']),
      ('clinic_insurance_contracts',array['clinic_admin','doctor','receptionist','finance'], array['clinic_admin','finance'],                array['clinic_admin']),
      ('patients',                  array['clinic_admin','doctor','receptionist','finance'], array['clinic_admin','receptionist','doctor'],  array['clinic_admin']),
      ('patient_consents',          array['clinic_admin','doctor','receptionist'],            array['clinic_admin','receptionist'],           array['clinic_admin']),
      ('appointments',              array['clinic_admin','doctor','receptionist','finance'], array['clinic_admin','receptionist','doctor'],  array['clinic_admin']),
      ('appointment_status_history',array['clinic_admin','doctor','receptionist','finance'], array['clinic_admin','doctor','receptionist','finance'], array['clinic_admin']),
      ('waiting_list',              array['clinic_admin','doctor','receptionist'],            array['clinic_admin','receptionist'],           array['clinic_admin','receptionist']),
      ('allergies',                 array['clinic_admin','doctor','receptionist'],            array['clinic_admin','doctor'],                 array['clinic_admin','doctor']),
      ('exam_orders',               array['clinic_admin','doctor','receptionist','finance'], array['clinic_admin','doctor','receptionist'],  array['clinic_admin']),
      ('exam_order_items',          array['clinic_admin','doctor','receptionist','finance'], array['clinic_admin','doctor','receptionist'],  array['clinic_admin']),
      ('exam_results',              array['clinic_admin','doctor','receptionist'],            array['clinic_admin','doctor'],                 array['clinic_admin']),
      ('insurance_claims',          array['clinic_admin','finance','receptionist'],           array['clinic_admin','finance'],                array['clinic_admin']),
      ('financial_transactions',    array['clinic_admin','finance'],                          array['clinic_admin','finance'],                array['clinic_admin']),
      ('inventory_items',           array['clinic_admin','doctor','receptionist','finance'], array['clinic_admin','finance'],                array['clinic_admin']),
      ('inventory_movements',       array['clinic_admin','doctor','receptionist','finance'], array['clinic_admin','finance'],                array['clinic_admin']),
      ('documents',                 array['clinic_admin','doctor','receptionist'],            array['clinic_admin','doctor','receptionist'],  array['clinic_admin']),
      ('whatsapp_messages',         array['clinic_admin','doctor','receptionist'],            array['clinic_admin','doctor','receptionist'],  array['clinic_admin'])
    ) as t(tbl, read_roles, write_roles, delete_roles)
  loop
    execute format('alter table %I enable row level security', r.tbl);
    execute format('drop policy if exists tenant_select on %I', r.tbl);
    execute format('drop policy if exists tenant_insert on %I', r.tbl);
    execute format('drop policy if exists tenant_update on %I', r.tbl);
    execute format('drop policy if exists tenant_delete on %I', r.tbl);

    execute format(
      'create policy tenant_select on %I for select using (app_has_any_role(clinic_id, %L::text[]))',
      r.tbl, r.read_roles
    );
    execute format(
      'create policy tenant_insert on %I for insert with check (app_has_any_role(clinic_id, %L::text[]))',
      r.tbl, r.write_roles
    );
    execute format(
      'create policy tenant_update on %I for update using (app_has_any_role(clinic_id, %L::text[])) with check (app_has_any_role(clinic_id, %L::text[]))',
      r.tbl, r.write_roles, r.write_roles
    );
    execute format(
      'create policy tenant_delete on %I for delete using (app_has_any_role(clinic_id, %L::text[]))',
      r.tbl, r.delete_roles
    );
  end loop;
end $$;

-- Prontuário: somente admin clínico e médicos; escrita restrita ao profissional --
alter table medical_records enable row level security;
create policy medical_records_select on medical_records
  for select using (app_has_any_role(clinic_id, array['clinic_admin','doctor']));
create policy medical_records_insert on medical_records
  for insert with check (
    app_has_any_role(clinic_id, array['clinic_admin'])
    or (app_has_any_role(clinic_id, array['doctor']) and professional_id = app_professional_id(clinic_id))
  );
create policy medical_records_update on medical_records
  for update using (
    app_has_any_role(clinic_id, array['clinic_admin'])
    or (app_has_any_role(clinic_id, array['doctor']) and professional_id = app_professional_id(clinic_id))
  ) with check (
