s', 'Limites', 'Usuários, unidades e IA.', 20), ('plataforma-planos', 'precos', 'Preços', 'Mensal e anual.', 30), ('plataforma-modulos', 'catalogo-modulos', 'Catálogo', 'Módulos e categorias.', 10), ('plataforma-modulos', 'funcionalidades', 'Funcionalidades', 'Detalhe por módulo.', 20), ('plataforma-modulos', 'adocao', 'Adoção', 'Clínicas por módulo.', 30), ('plataforma-assinaturas', 'contratos', 'Contratos', 'Vigência e condições.', 10), ('plataforma-assinaturas', 'status', 'Status', 'Teste, ativa e inadimplente.', 20), ('plataforma-assinaturas', 'renovacoes', 'Renovações', 'Ciclos e vencimentos.', 30), ('plataforma-pagamentos', 'faturas', 'Faturas', 'Emissão e baixa.', 10), ('plataforma-pagamentos', 'registro-pagamentos', 'Registro de pagamentos', 'Baixa manual e conciliação.', 20), ('plataforma-pagamentos', 'gateway', 'Gateway', 'Stripe, Asaas e manual.', 30), ('plataforma-relatorios', 'receita', 'Receita', 'MRR, ARR e inadimplência.', 10), ('plataforma-relatorios', 'adocao-modulos', 'Adoção de módulos', 'Uso por clínica.', 20), ('plataforma-relatorios', 'exportacao', 'Exportação', 'CSV e PDF.', 30), ('plataforma-configuracoes', 'padroes-plataforma', 'Padrões', 'Teste, periodicidade e contato.', 10), ('plataforma-configuracoes', 'gateway', 'Gateway', 'Provedor padrão.', 20), ('plataforma-configuracoes', 'observacoes', 'Observações', 'Notas internas.', 30) ) as v(module_key, feature_key, name, description, sort_order) join modules m on m.key = v.module_key on conflict (module_id, key) do update set name = excluded.name, description = excluded.description, sort_order = excluded.sort_order;
-- Planos ---------------------------------------------------------------------- insert into plans (name, slug, description, monthly_price, annual_price, user_limit, professional_limit, unit_limit, patient_limit, storage_gb, ai_interaction_limit, message_limit, trial_days, is_active, sort_order) values ('Essencial', 'essential', 'Para consultórios que estão organizando a operação.', 189.00, 1890.00, 3, 2, 1, 500, 5, 100, 200, 14, true, 10), ('Profissional', 'professional', 'Para clínicas com equipe, prontuário e convênios.', 349.00, 3490.00, 10, 5, 2, 2000, 20, 500, 1000, 14, true, 20), ('Empresarial', 'enterprise', 'Para redes com várias unidades e alto volume.', 690.00, 6900.00, 30, 15, 5, 10000, 100, 2000, 5000, 14, true, 30) on conflict (slug) do update set name = excluded.name, description = excluded.description, monthly_price = excluded.monthly_price, annual_price = excluded.annual_price, user_limit = excluded.user_limit, professional_limit = excluded.professional_limit, unit_limit = excluded.unit_limit, patient_limit = excluded.patient_limit, storage_gb = excluded.storage_gb, ai_interaction_limit = excluded.ai_interaction_limit, message_limit = excluded.message_limit, trial_days = excluded.trial_days;
-- Módulos por plano ----------------------------------------------------------- insert into plan_modules (plan_id, module_id) select p.id, m.id from (values ('essential', 'painel'), ('essential', 'agenda'), ('essential', 'consultas'), ('essential', 'pacientes'), ('professional', 'painel'), ('professional', 'agenda'), ('professional', 'consultas'), ('professional', 'pacientes'), ('professional', 'prontuarios'), ('professional', 'prescricoes'), ('professional', 'exames'), ('professional', 'financeiro'), ('professional', 'convenios'), ('professional', 'medicos'), ('enterprise', 'painel'), ('enterprise', 'agenda'), ('enterprise', 'consultas'), ('enterprise', 'pacientes'), ('enterprise', 'prontuarios'), ('enterprise', 'prescricoes'), ('enterprise', 'exames'), ('enterprise', 'financeiro'), ('enterprise', 'convenios'), ('enterprise', 'medicos'), ('enterprise', 'estoque'), ('enterprise', 'unidades') ) as v(plan_slug, module_key) join plans p on p.slug = v.plan_slug join modules m on m.key = v.module_key on conflict (plan_id, module_id) do nothing;
-- Configurações iniciais da plataforma ---------------------------------------- insert into platform_settings (key, value) values ('platform.name', '{"value":"ClinicOS"}'::jsonb), ('platform.support_email', '{"value":"suporte@clinicos.app"}'::jsonb), ('platform.default_trial_days', '{"value":14}'::jsonb), ('platform.default_gateway', '{"value":"stripe"}'::jsonb), ('platform.default_periodicity', '{"value":"mensal"}'::jsonb), ('platform.whatsapp_mode', '{"value":"manual"}'::jsonb), ('platform.ai_guardrails', '{"diagnosis":false,"prescribing":false,"human_review":true}'::jsonb) on conflict (key) do nothing;
-- Categorias financeiras padrão (globais) -------------------------------------- insert into financial_categories (clinic_id, name, type, is_system) values (null, 'Consulta', 'receita', true), (null, 'Retorno', 'receita', true), (null, 'Procedimento', 'receita', true), (null, 'Exame', 'receita', true), (null, 'Convênio', 'receita', true), (null, 'Venda de produto', 'receita', true), (null, 'Salários', 'despesa', true), (null, 'Aluguel', 'despesa', true), (null, 'Materiais', 'despesa', true), (null, 'Impostos', 'despesa', true), (null, 'Marketing', 'despesa', true), (null, 'Outros', 'despesa', true) on conflict do nothing;

