-- Administrador da clínica: todos os módulos de clínica ------------------------ insert into role_permissions (role, permission_id) select 'clinic_admin', p.id from permissions p join modules m on m.id = p.module_id where m.audience = 'clinica' on conflict do nothing;
-- Médico ----------------------------------------------------------------------- insert into role_permissions (role, permission_id) select 'doctor', p.id from permissions p where p.key = any (array[ 'painel:view', 'agenda:view', 'agenda:create', 'agenda:edit', 'consultas:view', 'consultas:create', 'consultas:edit', 'prontuarios:view', 'prontuarios:create', 'prontuarios:edit', 'prontuarios:sign', 'prontuarios:export', 'prescricoes:view', 'prescricoes:create', 'prescricoes:sign', 'prescricoes:cancel', 'exames:view', 'exames:create', 'exames:result', 'pacientes:view', 'pacientes:view_sensitive', 'medicos:view', 'unidades:view', 'convenios:view', 'estoque:view', 'relatorios:view', 'ia:use', 'whatsapp:view', 'whatsapp:send', 'portal:view', 'configuracoes:view', 'usuarios:view' ]) on conflict do nothing;
-- Recepcionista ---------------------------------------------------------------- insert into role_permissions (role, permission_id) select 'receptionist', p.id from permissions p where p.key = any (array[ 'painel:view', 'agenda:view', 'agenda:create', 'agenda:edit', 'agenda:delete', 'consultas:view', 'consultas:create', 'pacientes:view', 'pacientes:view_sensitive', 'pacientes:create', 'pacientes:edit', 'medicos:view', 'unidades:view', 'convenios:view', 'estoque:view', 'exames:view', 'exames:create', 'prescricoes:view', 'relatorios:view', 'whatsapp:view', 'whatsapp:send', 'portal:view', 'configuracoes:view' ]) on conflict do nothing;
-- Financeiro ------------------------------------------------------------------- insert into role_permissions (role, permission_id) select 'finance', p.id from permissions p where p.key = any (array[ 'painel:view', 'financeiro:view', 'financeiro:create', 'financeiro:edit', 'financeiro:delete', 'financeiro:export', 'convenios:view', 'convenios:create', 'convenios:edit', 'convenios:approve', 'estoque:view', 'estoque:create', 'estoque:edit', 'estoque:delete', 'pacientes:view', 'medicos:view', 'unidades:view', 'agenda:view', 'consultas:view', 'exames:view', 'prescricoes:view', 'relatorios:view', 'relatorios:export', 'assinatura:view', 'configuracoes:view', 'whatsapp:view' ]) on conflict do nothing;
-- Paciente --------------------------------------------------------------------- insert into role_permissions (role, permission_id) select 'patient', p.id from permissions p where p.key = any (array[ 'portal:view', 'portal:appointments', 'portal:results', 'portal:documents', 'configuracoes:view' ]) on conflict do nothing;
-- Superadministrador da plataforma --------------------------------------------- insert into role_permissions (role, permission_id) select 'platform_admin', p.id from permissions p join modules m on m.id = p.module_id where m.audience = 'plataforma' on conflict do nothing;

-- ============================================================================= -- ClinicOS · 013 · Provisão de contas pela plataforma (somente escrita da conta) -- ============================================================================= -- O superadministrador não acessa dados clínicos por padrão. Esta migração -- concede ao papel de plataforma apenas a escrita nos registros de CONTA -- necessários para provisionar uma clínica contratada: -- · clinic_units (matriz e unidades cadastráveis pela plataforma) -- · clinic_memberships (vínculo inicial de administrador da clínica) -- · membership_units (vínculo entre adesão e unidade) -- · user_invites (convites de administrador no onboarding) -- Nenhuma delas contém dado clínico. Nenhum direito de leitura/escrita sobre -- pacientes, prontuários, receitas, laudos ou financeiro é concedido aqui. -- =============================================================================
create policy clinic_units_platform_write on clinic_units for all using (app_is_platform_admin()) with check (app_is_platform_admin());
create policy memberships_platform_write on clinic_memberships for all using (app_is_platform_admin()) with check (app_is_platform_admin());
create policy membership_units_platform_write on membership_units for all using (app_is_platform_admin()) with check (app_is_platform_admin());
create policy user_invites_platform_write on user_invites for all using (app_is_platform_admin()) with check (app_is_platform_admin());

-- ============================================================================= -- ClinicOS · 014 · Operação da clínica: limites de plano e aceite de convite -- ============================================================================= -- O acesso a `subscriptions` é restrito a admin/financeiro por RLS, mas a -- aplicação precisa dos limites do plano para qualquer perfil que cria -- registros (ex.: recepcionista criando pacientes). Em vez de abrir a tabela, -- expomos uma função SECURITY DEFINER guardada por vínculo ativo na clínica. -- =============================================================================
create or replace function app_plan_limits(p_clinic uuid) returns table ( plan_name text, user_limit integer, professional_limit integer, unit_limit integer, patient_limit integer ) language sql stable security definer set search_path = public, pg_temp as $$ select p.name::text, p.user_limit, p.professional_limit, p.unit_limit, p.patient_limit from subscriptions s join plans p on p.id = s.plan_id where s.clinic_id = p_clinic and s.status in ('em_teste', 'ativa', 'inadimplente', 'vencida') and app_is_member_of_clinic(p_clinic) order by (s.status = 'ativa') desc, s.current_period_end desc nulls last, s.started_at desc limit 1; $$;
do $$ begin if exists (select 1 from pg_roles where rolname = 'clinicos_app') then grant execute on function app_plan_limits(uuid) to clinicos_app; end if; end $$;
-- Diretório de pacientes: expõe colunas não sensíveis e mantém o CPF mascarado -- no banco para perfis sem `pacientes:view_sensitive`. Colunas novas são -- acrescentadas ao final para permitir `create or replace view`. create or replace view v_patients_directory with (security_invoker = true) as select p.id, p.clinic_id, p.full_name, p.social_name, case when app_has_permission(p.clinic_id, 'pacientes:view_sensitive') then p.cpf else app_mask_cpf(p.cpf) end as cpf, p.birth_date, p.sex, p.email, p.phone, p.whatsapp, p.city, p.state, p.status, ip.name as insurance_provider_name, p.lgpd_consent_at, p.created_at, p.updated_at from patients p left join insurance_providers ip on ip.id = p.insurance_provider_id;
-- Aceite de convite ----------------------------------------------------------- -- O convite é validado no banco (token, uso único e expiração) porque quem -- aceita ainda não é membro da clínica: nenhuma política de RLS o deixaria -- criar o próprio vínculo. A função é chamada pela aplicação com o hash do -- token; o link contém o token em claro, exibido uma única vez ao convidar. create or replace function app_accept_invite( p_token_hash text, p_full_name text, p_password_hash text ) returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$ declare v_invite user_invites%rowtype; v_user_id uuid; v_user_name text; v_existing users%rowtype; begin select * into v_invite from user_invites where token_hash = p_token_hash for update;
if not found then return jsonb_build_object('ok', false, 'error', 'invalido'); end if;
if v_invite.status <> 'pendente' then return jsonb_build_object('ok', false, 'error', 'utilizado'); end if;
if v_invite.expires_at <= now() then update user_invites set status = 'expirado' where id = v_invite.id; return jsonb_build_object('ok', false, 'error', 'expirado'); end if;
v_user_name := coalesce(nullif(trim(p_full_name), ''), v_invite.full_name);
if v_user_name is null or length(v_user_name) < 3 then return jsonb_build_object('ok', false, 'error', 'nome'); end if;
if p_password_hash is null or length(p_password_hash) < 20 then return jsonb_build_object('ok', false, 'error', 'senha'); end if;
select * into v_existing from users where lower(email) = lower(v_invite.email) limit 1;
if v_existing.id is not null then v_user_id := v_existing.id; else insert into users (email, password_hash, full_name, status, email_verified_at) values (lower(v_invite.email), p_password_hash, v_user_name, 'ativo', now()) returning id into v_user_id; end if;
-- Quem aceita passa a ser o ator da própria admissão (auditoria). perform set_config('app.user_id', v_user_id::text, true); perform set_config('app.clinic_id', v_invite.clinic_id::text, true);
insert into clinic_memberships (clinic_id, user_id, role, status, invited_by) values (v_invite.clinic_id, v_user_id, v_invite.role, 'ativo', v_invite.invited_by) on conflict (clinic_id, user_id) do update set role = excluded.role, status = 'ativo', updated_at = now();
-- Atribuição padrão: todas as unidades ativas da clínica. insert into membership_units (membership_id, unit_id, clinic_id) select m.id, u.id, m.clinic_id from clinic_memberships m join clinic_units u on u.clinic_id = m.clinic_id and u.status = 'ativa' where m.clinic_id = v_invite.clinic_id and m.user_id = v_user_id on conflict do nothing;
update user_invites set status = 'aceito', accepted_at = now() where id = v_invite.id;
return jsonb_build_object( 'ok', true, 'userId', v_user_id, 'clinicId', v_invite.clinic_id, 'email', lower(v_invite.email), 'existingUser', v_existing.id is not null ); end; $$;
do $$ begin if exists (select 1 from pg_roles where rolname = 'clinicos_app') then grant execute on function app_accept_invite(text, text, text) to clinicos_app; end if; end $$;

-- =============================================================================
-- ClinicOS · 015 · Status do convite (página pública de aceite)
-- =============================================================================

create or replace function app_invite_status(p_token_hash text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v record;
begin
  select status::text as status, email, full_name, expires_at
    into v
    from user_invites
   where token_hash = p_token_hash
   limit 1;

  if not found then
    return jsonb_build_object('found', false);
  end if;

  return jsonb_build_object(
    'found', true,
    'status', v.status,
    'email', v.email,
    'fullName', v.full_name,
    'expiresAt', v.expires_at,
    'valid', (v.status = 'pendente' and v.expires_at > now())
  );
end;
$$;

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'clinicos_app') then
    grant execute on function app_invite_status(text) to clinicos_app;
  end if;
end $$;

-- =============================================================================
-- ClinicOS · 016 · Verificação pública de documento
-- =============================================================================

create or replace function app_verify_document(p_code text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_type text := null;
  v_status text := null;
  v_signed_at timestamptz := null;
  v_professional text := null;
  v_version integer := null;
begin
  select 'prontuario', mr.status::text, mr.signed_at, pr.full_name, mr.version
    into v_type, v_status, v_signed_at, v_professional, v_version
    from medical_records mr
    join professionals pr on pr.id = mr.professional_id
   where mr.verification_code = p_code
   limit 1;

  if v_type is null then
    select 'prescricao', pr.status::text, pr.signed_at, prof.full_name, 1
      into v_type, v_status, v_signed_at, v_professional, v_version
      from prescriptions pr
      join professionals prof on prof.id = pr.professional_id
     where pr.verification_code = p_code
     limit 1;
  end if;

  if v_type is null then
    return jsonb_build_object('found', false);
  end if;

  return jsonb_build_object(
    'found', true,
    'type', v_type,
    'status', v_status,
    'signedAt', v_signed_at,
    'professional', v_professional,
    'version', v_version,
    'valid', (v_status in ('assinado', 'emitida'))
  );
end;
$$;

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'clinicos_app') then
    grant execute on function app_verify_document(text) to clinicos_app;
  end if;
end $$;

-- ============================================================================= -- ClinicOS · 017 · Renomeia "Clientes" para "Clínicas" na plataforma -- ============================================================================= -- A área de gestão de tenants da plataforma passa a se chamar "Clínicas" em -- rotas, rótulos, catálogo de módulos e permissões. Esta migration é -- idempotente: em instalações novas (011/012 já renomeados) nada é alterado.
-- Catálogo de módulos da plataforma ----------------------------------------- update modules set key = 'plataforma-clinicas', name = 'Clínicas', description = 'Cadastro e contratação de clínicas.', route = '/admin/clinicas', updated_at = now() where key = 'plataforma-clientes';
-- Funcionalidades do módulo ------------------------------------------------ update module_features set key = 'visao-clinicas' where key = 'visao-clientes';
update module_features set name = 'Visão de clínicas' where name = 'Visão de clientes';
-- Permissões (RBAC) -------------------------------------------------------- update permissions set key = replace(key, 'plataforma-clientes:', 'plataforma-clinicas:'), description = case key when 'plataforma-clientes:view' then 'Visualizar clínicas' when 'plataforma-clientes:create' then 'Criar clínica' when 'plataforma-clientes:edit' then 'Editar clínica' else description end where key like 'plataforma-clientes:%';

